INSERT IGNORE INTO vendor_listings (id, name, category, city, district, price_range, description, portfolio_json, rating, spotlight, owner_email) VALUES ('vw-01', 'Kandyan Reach Hotel', 'Venue & Res. Halls', 'Kurunegala', 'Kurunegala', '735000-1110000', 'Kurunegala wedding hotel with four all-inclusive packages from Rs. 4,900 to Rs. 7,400 per person (minimum 150 pax). Compliments include couple, registration and head tables, pool/lobby/pond photo locations, outdoor registration, changing room, decorated honeymoon room, dance floor and DJ/band stage.', '{"images": [], "quotations": [{"id": "kr-unity", "title": "Unity KRH Wedding Package", "price": "4900", "details": "Per person, min 150 pax. Menu: 1 welcome drink, 1 appetizer, 1 shooter, 5 salads, 4 dressings, 1 soup, steamed rice, 1 flavoured rice, noodles/pasta, chicken, fish, 4 veg, all condiments, 5 desserts. Compliments: tables, pool/lobby/pond photo locations, outdoor registration, changing room, honeymoon room, dance floor, DJ/band stage."}, {"id": "kr-essential", "title": "Essential Elegance Package", "price": "5300", "details": "Per person. Menu upgrades to 2 appetizers, 2 shooters, 7 salads, all dressings, 2 flavoured rice, 7 desserts. Adds wedding cards, unlimited bites and unlimited soft drinks."}, {"id": "kr-grand", "title": "Grand Celebration Package", "price": "6000", "details": "Same menu grid as Essential. Adds flower decorations, poruwa and settee back, Ashtaka, welcome dancers, Jayamangala Gatha, kiri kala, oil lamp and champagne fondant."}, {"id": "kr-bliss", "title": "Infinite Bliss Package", "price": "7400", "details": "Menu: 4 appetizers, 3 shooters, 9 salads, 2 soups, 3 flavoured rice, plus crabs or pork. Adds wedding car (25 km) and DJ with stage."}, {"id": "kr-addon", "title": "Add-on meats, bites and bar", "price": "300", "details": "Beef 400 pp, pork 300 pp, mutton 650 pp, action cooking per kg 3500-9000, dessert action 375, ice coffee at Mangala Sabawa 550. Bites per kg 2000-9000. Soft drinks 550-1400. Beer 1590-2350."}], "quotationPdf": null, "categories": ["Venue & Res. Halls", "Caters"], "districts": ["Kurunegala"]}', 4.7, 1, NULL);
