INSERT IGNORE INTO vendor_listings (id, name, category, city, district, price_range, description, portfolio_json, rating, spotlight, owner_email) VALUES ('vw-36', 'Seethawaka Regency', 'Venue & Res. Halls', 'Avissawella', 'Colombo', '200000-2000000', 'Luxury hotel and iconic wedding venue with 12+ years. All-inclusive 2026-2027 Silver, Gold, Platinum and Regency packages: grand buffet, floral decorations, entertainment, wedding cake, luxury wedding car, bites and soft drinks. Halls: Grand Ballroom 400, Diamond Ballroom 250, Golden Court 50, Kings Pool Side 75, outdoor garden/pool 200.', '{"images": [], "quotations": [{"id": "sr-sv", "title": "Silver all-inclusive 2026-2027", "price": "", "details": "Grand buffet, floral decorations, entertainment, cake, luxury wedding car, bites and soft drinks."}, {"id": "sr-gd", "title": "Gold all-inclusive 2026-2027", "price": "", "details": "Higher-tier buffet and ceremony inclusions."}, {"id": "sr-pt", "title": "Platinum all-inclusive 2026-2027", "price": "", "details": "Premium all-inclusive celebration."}, {"id": "sr-rg", "title": "Regency all-inclusive 2026-2027", "price": "", "details": "Top exclusive Regency service package."}, {"id": "sr-halls", "title": "Signature venues", "price": "0", "details": "Grand Ballroom 400 pax, Diamond Ballroom 250 (20m chandelier), Golden Court 50, Kings Pool Side 75, outdoor garden and pool 200."}], "quotationPdf": null, "categories": ["Venue & Res. Halls", "Caters"], "districts": ["Colombo"]}', 4.8, 1, NULL);
INSERT IGNORE INTO vendor_listings (id, name, category, city, district, price_range, description, portfolio_json, rating, spotlight, owner_email) VALUES ('vw-37', 'The Blue Water Hotel and Spa', 'Venue & Res. Halls', 'Wadduwa', 'Kalutara', '9185-12445', 'Ocean-view weddings. Magical Weddings menu options 01-03 billed per person plus 10% service charge and government taxes.', '{"images": [], "quotations": [{"id": "bw-1", "title": "Option 01", "price": "9185", "details": "++ 10% SC + tax. 6 appetizers/salads, 1 soup, 3 rice/noodles/pasta, fish, seafood live, chicken, pork, mutton or beef, 3 veg, 5 desserts."}, {"id": "bw-2", "title": "Option 02", "price": "10850", "details": "++. 7 appetizers/salads + salad action, 4 rice/noodles/pasta, 6 desserts."}, {"id": "bw-3", "title": "Option 03", "price": "12445", "details": "++. 9 appetizers/salads, prawn live, mutton or lamb, 4 veg, 7 desserts. Pork/beef can upgrade to carvery."}], "quotationPdf": null, "categories": ["Venue & Res. Halls", "Caters"], "districts": ["Kalutara"]}', 4.8, 1, NULL);
INSERT IGNORE INTO vendor_listings (id, name, category, city, district, price_range, description, portfolio_json, rating, spotlight, owner_email) VALUES ('vw-38', 'Grand Mondo Luxury Banquets', 'Venue & Res. Halls', 'Homagama', 'Colombo', '380000-1900000', 'Panaluwa, Watareka banquet hotel. All-inclusive wedding package Rs. 380,000 net covers decorations, traditional ceremony team, DJ, LED wall, 2-hour open bar, 15 kg bites, wedding car 10 hrs/30 km. Gold menu noted at 6,219 x 200 pax. Platinum menu Rs. 8,500 and Diamond Rs. 9,500.', '{"images": [], "quotations": [{"id": "gmd-all", "title": "All Inclusive Wedding Package", "price": "380000", "details": "Flower decorations, settee, traditional fittings, oil lamp, milk or champagne fountain, cake starch or Saubagya, Ashtaka, Jayamangala Gatha (3 girls), dancing or Indian drums, DJ + lights + smoke, LED wall, Salupaliya or Western dance, 2-hour open bar, 15 kg cooked bites, photo location, morning tea, event manager, 2 changing rooms, wedding car (Benz/BMW/Defender/Audi) 10 hrs 30 km with deco. Free service charge and electricity."}, {"id": "gmd-gold", "title": "Gold menu 200 pax (handwritten)", "price": "1243800", "details": "Gold menu 6,219 x 200 noted on flyer, plus 330,000 ceremony extras."}, {"id": "gmd-pt", "title": "Platinum Menu", "price": "8500", "details": "Per person. 1 welcome drink, 1 hot pot, 7 salads, 3 rice, 1 noodles/pasta, 5 veg, 3 meat/seafood, 8 desserts. 38 varieties."}, {"id": "gmd-dia", "title": "Diamond Menu", "price": "9500", "details": "Per person. 2 hot pots, 9 salads, 3 rice, 2 noodles/pasta, 6 veg, 4 meat/seafood, 9 desserts. 48 varieties."}], "quotationPdf": null, "categories": ["Venue & Res. Halls", "Caters", "Floral & Deco"], "districts": ["Colombo"]}', 4.7, 1, 'grandmondobanquet@gmail.com');
